using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorAudioRecorderOperations
{
    private static Settings StartResult(bool done,string error,Settings? preferences=null)=>new Settings{["done"]=done,["error"]=error,["preferences"]=preferences??new Settings()};
    public Settings prepare_start(Node owner,Settings active)
    {
        if(owner.Get("recording").AsBool())return StartResult(true,"");var preferences=requested_preferences(owner);string error=preference_error(preferences);if(error.Length>0)return StartResult(true,error);owner.Set("record_timeline",Get(preferences,"record_timeline",false));owner.Set("monitor_timeline",monitors_timeline(preferences));if(DisplayServer.GetName()=="headless")return StartResult(true,"Audio capture is unavailable in headless mode.");bool mic=Get(preferences,"record_mic",false).AsBool();if(mic&&!ProjectSettings.GetSetting("audio/driver/enable_input",false).AsBool())return StartResult(true,"Microphone input is disabled. Restart the application to enable recording.");if(mic&&AudioServer.GetInputDeviceList().Length==0)return StartResult(true,"No microphone input device is available.");owner.Set("_mono",preferences["mono"]);owner.Set("_capture_problem","");if(owner.Get("disk_backed").AsBool()){string directory=ProjectSettings.GlobalizePath("user://audio_workspace/takes/"+new ActorDataOperations().new_id());owner.Set("_take_directory",directory);if(DirAccess.MakeDirRecursiveAbsolute(directory)!=Error.Ok){cleanup(owner,active);return StartResult(true,"Could not create the disk-backed take folder.");}active[directory.Replace('\\','/').SimplifyPath()]=true;using var journal=new ConfigFile();journal.SetValue("take","state","capturing");journal.SetValue("take","started",Time.GetUnixTimeFromSystem());journal.SetValue("take","preferences",preferences);if(journal.Save(directory.PathJoin("take.cfg"))!=Error.Ok){cleanup(owner,active);return StartResult(true,"Could not create the take recovery journal.");}}
        if(Get(preferences,"record_system",false).AsBool()){var system=new WindowsSystemAudio();owner.Set("system_capture",system);owner.AddChild(system);}return StartResult(false,"",preferences);
    }
    private string StartWriter(Node owner,string key,string filename){var writer=new NativeAudioTakeWriter();owner.Set(key,writer);return writer.Call("start",owner.Get("_take_directory").AsString().PathJoin(filename),(int)AudioServer.GetMixRate(),owner.Get("_mono")).AsString();}
    public string complete_start(Node owner,Settings preferences,string systemError,Settings active)
    {
        if(systemError.Length>0){cleanup(owner,active);return systemError;}bool mic=Get(preferences,"record_mic",false).AsBool(),system=Get(preferences,"record_system",false).AsBool(),monitor=owner.Get("monitor_timeline").AsBool(),disk=owner.Get("disk_backed").AsBool();if(mic){string device=preferences["device"].AsString();AudioServer.InputDevice=Array.IndexOf(AudioServer.GetInputDeviceList(),device)>=0?device:"Default";}foreach(string key in new[]{"peaks","_system_peaks","_mic_peaks","_timeline_peaks"})owner.Set(key,Array.Empty<float>());foreach(string key in new[]{"_peak","_system_peak","_timeline_peak"})owner.Set(key,0.0);foreach(string key in new[]{"_peak_frames","_system_frames","_timeline_frames"})owner.Set(key,0);
        if(owner.Get("record_timeline").AsBool()&&(!system||!monitor)){string name="ActorTimelineRecording_"+owner.GetInstanceId();owner.Set("timeline_bus_name",name);AudioServer.AddBus(1);AudioServer.SetBusName(1,name);AudioServer.SetBusSend(1,"Master");AudioServer.SetBusMute(1,!monitor);var capture=new AudioEffectCapture{BufferLength=.5f};owner.Set("timeline_capture",capture);AudioServer.AddBusEffect(1,capture);if(disk){string error=StartWriter(owner,"_timeline_writer","timeline.wav");if(error.Length>0){cleanup(owner,active);return error;}}else{var effect=new AudioEffectRecord{Format=AudioStreamWav.FormatEnum.Format16Bits};owner.Set("timeline_effect",effect);AudioServer.AddBusEffect(1,effect);effect.SetRecordingActive(true);}}
        if(!mic){owner.Set("recording",true);return "";}string busName="ActorMicrophone_"+owner.GetInstanceId();owner.Set("bus_name",busName);AudioServer.AddBus();int bus=AudioServer.BusCount-1;AudioServer.SetBusName(bus,busName);AudioServer.SetBusMute(bus,true);var input=new AudioEffectCapture{BufferLength=.5f};owner.Set("capture",input);AudioServer.AddBusEffect(bus,input);if(disk){string error=StartWriter(owner,"_mic_writer","microphone.wav");if(error.Length>0){cleanup(owner,active);return error;}}else{var effect=new AudioEffectRecord{Format=AudioStreamWav.FormatEnum.Format16Bits};owner.Set("effect",effect);AudioServer.AddBusEffect(bus,effect);}var player=new AudioStreamPlayer{Stream=new AudioStreamMicrophone(),Bus=busName,VolumeDb=preferences["gain_db"].AsSingle()};owner.Set("player",player);owner.AddChild(player);Object<AudioEffectRecord>(owner,"effect")?.SetRecordingActive(true);player.Play();owner.Set("recording",true);return "";
    }
    public AudioStreamWav? prepare_stop(Node owner){owner.Set("recording",false);var effect=Object<AudioEffectRecord>(owner,"effect");if(effect==null)return null;effect.SetRecordingActive(false);Object<AudioStreamPlayer>(owner,"player")?.Stop();return effect.GetRecording();}
    public AudioStreamWav? complete_stop(Node owner,AudioStreamWav? mic,AudioStreamWav? system,Settings active){AudioStreamWav? timeline=null;var effect=Object<AudioEffectRecord>(owner,"timeline_effect");if(effect!=null){effect.SetRecordingActive(false);timeline=effect.GetRecording();}var names=new List<string>();if(mic!=null)names.Add("Microphone");if(system!=null)names.Add("System");if(timeline!=null||owner.Get("record_timeline").AsBool())names.Add("Timeline");var stream=mix_streams(mix_streams(mic,system),timeline);cleanup(owner,active);if(stream==null||stream.GetLength()<=0)return null;stream.ResourceName=string.Join(" + ",names)+" Recording";if(owner.Get("_mono").AsBool()&&stream.Stereo)convert_to_mono(stream);return stream;}
    public Settings prepare_stop_files(Node owner)
    {
        if(!owner.Get("recording").AsBool()||!owner.Get("disk_backed").AsBool())return new Settings{["done"]=true,["result"]=new Settings{["error"]="No disk-backed recording is active.",["paths"]=new Godot.Collections.Array<string>()}};owner.Set("recording",false);var player=Object<AudioStreamPlayer>(owner,"player");if(GodotObject.IsInstanceValid(player))player!.Stop();drain_to_writer(Object<AudioEffectCapture>(owner,"capture"),Object<RefCounted>(owner,"_mic_writer"));drain_to_writer(Object<AudioEffectCapture>(owner,"timeline_capture"),Object<RefCounted>(owner,"_timeline_writer"));foreach(string key in new[]{"_mic_writer","_timeline_writer"})Object<RefCounted>(owner,key)?.Call("request_finish");return new Settings{["done"]=false,["directory"]=owner.Get("_take_directory")};
    }
    public bool writers_busy(Node owner){foreach(string key in new[]{"_mic_writer","_timeline_writer"})if(Object<RefCounted>(owner,key)?.Call("busy").AsBool()??false)return true;return false;}
    public Settings complete_stop_files(Node owner,string directory,Settings system,Settings active)
    {
        var paths=new Godot.Collections.Array<string>();var problems=new List<string>();string path=Get(system,"path","").AsString(),error=Get(system,"error","").AsString();if(path.Length>0)paths.Add(path);if(error.Length>0)problems.Add(error);foreach(string key in new[]{"_mic_writer","_timeline_writer"}){var writer=Object<RefCounted>(owner,key);if(writer==null)continue;var result=writer.Call("finish").AsGodotDictionary();if(result["frames"].AsInt64()>0)paths.Add(result["path"].AsString());error=result["error"].AsString();if(error.Length>0)problems.Add(error);}error=owner.Get("_capture_problem").AsString();if(error.Length>0)problems.Add(error);owner.Set("_mic_writer",default(Variant));owner.Set("_timeline_writer",default(Variant));var capture=new Settings{["paths"]=paths,["directory"]=directory,["mono"]=owner.Get("_mono"),["error"]=string.Join("; ",problems)};using var journal=new ConfigFile();journal.Load(directory.PathJoin("take.cfg"));journal.SetValue("take","state","captured");journal.SetValue("take","capture",capture);journal.Save(directory.PathJoin("take.cfg"));cleanup(owner,active);return capture;
    }
}
